<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8'); header('X-Content-Type-Options: nosniff'); header('Cache-Control: no-store'); header('Referrer-Policy: same-origin');
function out(int $s,array $p): never { http_response_code($s); echo json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
function input(): array { $d=json_decode(file_get_contents('php://input')?:'{}',true); if(!is_array($d))out(400,['error'=>'Corpo JSON inválido.']); return $d; }
function cfg(): array { $f=__DIR__.'/../config/database.php'; if(!is_file($f))out(500,['error'=>'Configuração ausente. Copie config/database.example.php para config/database.php e configure as credenciais.']); return require $f; }
function db(): PDO { static $pdo=null; if($pdo instanceof PDO)return $pdo; $c=cfg(); try{$pdo=new PDO("mysql:host={$c['host']};port={$c['port']};dbname={$c['database']};charset=utf8mb4",$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $pdo;}catch(Throwable $e){error_log('Cupcake DB: '.$e->getMessage());out(500,['error'=>'Falha de conexão com o banco. Verifique a configuração.']);} }
function admin(): void { $expected=(string)(cfg()['admin_token']??'');$given=(string)($_SERVER['HTTP_X_ADMIN_TOKEN']??'');if(strlen($expected)<32||!hash_equals($expected,$given))out(403,['error'=>'Acesso administrativo não autorizado.']); }
function productData(array $d): array { $n=trim((string)($d['name']??''));$desc=trim((string)($d['description']??''));$cat=trim((string)($d['category']??''));$price=filter_var($d['price']??null,FILTER_VALIDATE_FLOAT);$img=trim((string)($d['image']??''));if(mb_strlen($n)<2||mb_strlen($n)>120)out(422,['error'=>'Nome deve conter de 2 a 120 caracteres.']);if($desc===''||mb_strlen($desc)>1000)out(422,['error'=>'Descrição obrigatória, com até 1000 caracteres.']);if(!in_array($cat,['Clássicos','Especiais','Frutados'],true))out(422,['error'=>'Categoria inválida.']);if($price===false||$price<=0||$price>10000)out(422,['error'=>'Preço inválido.']);if($img!==''&&(!filter_var($img,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($img,PHP_URL_SCHEME)),['http','https'],true)))out(422,['error'=>'Imagem deve usar URL HTTP/HTTPS válida.']);return[$n,$desc,$cat,round((float)$price,2),$img]; }
$method=$_SERVER['REQUEST_METHOD']??'GET';$uri=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$path=preg_replace('#^.*?/api(?=/|$)#','',$uri);$seg=array_values(array_filter(explode('/',trim($path,'/')),'strlen'));$resource=$seg[0]??'';$id=isset($seg[1])&&ctype_digit($seg[1])?(int)$seg[1]:null;
try{$pdo=db();
 if($resource==='health'&&$method==='GET')out(200,['status'=>'ok','service'=>'Cupcake Gourmet API']);
 if($resource==='products'){
  if($method==='GET'&&$id===null){$rows=$pdo->query('SELECT id,name,description,category,price,rating,tag,image FROM products WHERE active=1 ORDER BY id')->fetchAll();foreach($rows as &$r)$r['price']=(float)$r['price'];unset($r);out(200,['data'=>$rows]);}
  if($method==='GET'&&$id!==null){$q=$pdo->prepare('SELECT id,name,description,category,price,rating,tag,image FROM products WHERE id=? AND active=1');$q->execute([$id]);$r=$q->fetch();if(!$r)out(404,['error'=>'Produto não encontrado.']);$r['price']=(float)$r['price'];out(200,['data'=>$r]);}
  if(in_array($method,['POST','PUT','PATCH'],true)){admin();$d=input();[$n,$desc,$cat,$price,$img]=productData($d);$rating=filter_var($d['rating']??4.8,FILTER_VALIDATE_FLOAT);if($rating===false||$rating<0||$rating>5)out(422,['error'=>'Avaliação deve estar entre 0 e 5.']);$tag=mb_substr(trim((string)($d['tag']??'Artesanal')),0,60);if($method==='POST'){$q=$pdo->prepare('INSERT INTO products(name,description,category,price,rating,tag,image,active) VALUES(?,?,?,?,?,?,?,1)');$q->execute([$n,$desc,$cat,$price,$rating,$tag,$img]);out(201,['message'=>'Produto criado.','id'=>(int)$pdo->lastInsertId()]);}if($id===null)out(400,['error'=>'Informe o ID na URL.']);$q=$pdo->prepare('UPDATE products SET name=?,description=?,category=?,price=?,rating=?,tag=?,image=? WHERE id=? AND active=1');$q->execute([$n,$desc,$cat,$price,$rating,$tag,$img,$id]);$check=$pdo->prepare('SELECT id FROM products WHERE id=? AND active=1');$check->execute([$id]);if(!$check->fetch())out(404,['error'=>'Produto não encontrado.']);out(200,['message'=>'Produto atualizado.']);}
  if($method==='DELETE'&&$id!==null){admin();$q=$pdo->prepare('UPDATE products SET active=0 WHERE id=? AND active=1');$q->execute([$id]);if(!$q->rowCount())out(404,['error'=>'Produto não encontrado.']);out(200,['message'=>'Produto desativado.']);}out(405,['error'=>'Método não permitido.']);
 }
 if($resource==='orders'&&$method==='POST'){$d=input();$name=trim((string)($d['name']??''));$email=trim((string)($d['email']??''));$phone=trim((string)($d['phone']??''));$address=trim((string)($d['address']??''));$payment=trim((string)($d['payment']??''));$items=$d['items']??null;
  if(mb_strlen($name)<3||mb_strlen($name)>150)out(422,['error'=>'Informe seu nome completo.']);if(mb_strlen($email)>254||!filter_var($email,FILTER_VALIDATE_EMAIL))out(422,['error'=>'E-mail inválido.']);if(mb_strlen($phone)<8||mb_strlen($phone)>30)out(422,['error'=>'Telefone inválido.']);if(mb_strlen($address)<8||mb_strlen($address)>500)out(422,['error'=>'Informe um endereço completo.']);if(!in_array($payment,['Pix (simulação)','Cartão (simulação)','Pagamento na entrega (simulação)'],true))out(422,['error'=>'Forma de pagamento inválida.']);if(!is_array($items)||count($items)<1||count($items)>30)out(422,['error'=>'O pedido deve conter de 1 a 30 produtos diferentes.']);$qtys=[];foreach($items as $it){if(!is_array($it))out(422,['error'=>'Item inválido.']);$pid=filter_var($it['id']??null,FILTER_VALIDATE_INT);$qty=filter_var($it['qty']??null,FILTER_VALIDATE_INT);if(!$pid||!$qty||$qty<1||$qty>20)out(422,['error'=>'Produto ou quantidade inválida (máximo 20).']);$qtys[$pid]=($qtys[$pid]??0)+$qty;if($qtys[$pid]>20)out(422,['error'=>'Quantidade máxima excedida.']);}
  $pdo->beginTransaction();$ids=array_keys($qtys);$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT id,name,price FROM products WHERE active=1 AND id IN ($marks)");$q->execute($ids);$products=[];foreach($q->fetchAll() as $p)$products[(int)$p['id']]=$p;if(count($products)!==count($ids)){$pdo->rollBack();out(422,['error'=>'Um ou mais produtos não estão disponíveis. Atualize o catálogo.']);}$subtotal=0.0;foreach($qtys as $pid=>$qty)$subtotal+=(float)$products[$pid]['price']*$qty;$fee=8.00;$total=round($subtotal+$fee,2);$code='CG-'.strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare('INSERT INTO orders(order_code,customer_name,email,phone,address,payment_method,status,subtotal,delivery_fee,total) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$code,$name,$email,$phone,$address,$payment,'Recebido',round($subtotal,2),$fee,$total]);$orderId=(int)$pdo->lastInsertId();$itStmt=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)');foreach($qtys as $pid=>$qty)$itStmt->execute([$orderId,$pid,$products[$pid]['name'],$qty,$products[$pid]['price']]);$pdo->commit();out(201,['message'=>'Pedido registrado. Pagamento não processado: modo de demonstração.','data'=>['id'=>$orderId,'code'=>$code,'status'=>'Recebido','subtotal'=>round($subtotal,2),'delivery_fee'=>$fee,'total'=>$total]]);
 }
 if($resource==='orders'&&$method==='GET'&&$id!==null){$q=$pdo->prepare('SELECT id,order_code,status,subtotal,delivery_fee,total,created_at FROM orders WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)out(404,['error'=>'Pedido não encontrado.']);foreach(['subtotal','delivery_fee','total'] as $k)$r[$k]=(float)$r[$k];out(200,['data'=>$r]);}
 out(404,['error'=>'Rota não encontrada.']);
}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();error_log('Cupcake API: '.$e->getMessage());out(500,['error'=>'Erro interno ao processar a solicitação.']);}
